The `any` type is used for the page object. Consider defining a proper type/interface for page configuration to improve type safety.
```suggestion
interface PageConfig {
  name: string;
  context?: Record<string, unknown>;
  [key: string]: unknown;
}

export function PageView() {
  const { pageName } = useParams<{ pageName: string }>();
  const [searchParams] = useSearchParams();

  // Find page definition in config
  // In a real implementation, this would fetch from the server
  const page = appConfig.pages?.find((p: PageConfig) => p.name === pageName);
```

The `any` type is used for the dashboard object. Consider defining a proper type/interface for dashboard configuration to improve type safety.
```suggestion
interface DashboardConfig {
  name: string;
  label?: string;
  description?: string;
  [key: string]: unknown;
}

export function DashboardView() {
  const { dashboardName } = useParams<{ dashboardName: string }>();

  // Find dashboard definition in config
  // In a real implementation, this would fetch from the server
  const dashboard = (appConfig.dashboards as DashboardConfig[] | undefined)?.find(
    (d: DashboardConfig) => d.name === dashboardName
  );
```

